def is_valid_pmf(pmf: dict, tol: float = 1e-9) -> bool:
    non_negative = all(p >= 0 for p in pmf.values())
    normalizes = abs(sum(pmf.values()) - 1.0) < tol
    return non_negative and normalizes

candidates = {
    "fair_die": {k: 1 / 6 for k in range(1, 7)},
    "undernormalized": {1: 0.3, 2: 0.3, 3: 0.3},          # sums to 0.9
    "negative_entry": {1: 0.5, 2: 0.6, 3: -0.1},           # sums to 1.0, but invalid
}

for name, pmf in candidates.items():
    print(name, "-> valid:", is_valid_pmf(pmf), "sum:", round(sum(pmf.values()), 4))

