import math

def binomial_pmf(n, k, p):
    return math.comb(n, k) * p**k * (1 - p)**(n - k)

n, p = 4, 0.5
pmf = {k: binomial_pmf(n, k, p) for k in range(n + 1)}
print(sum(pmf.values()))   # 1.0

from scipy.stats import norm

def prob_between(a, b, mu, sigma):
    dist = norm(loc=mu, scale=sigma)
    return dist.cdf(b) - dist.cdf(a)

print(prob_between(1, 3, 0, 1))   # a small positive probability

import numpy as np

joint = np.array([
    [0.10, 0.20, 0.05],
    [0.15, 0.30, 0.20],
])

def conditional_y_given_x(joint, x_index):
    return joint[x_index] / joint[x_index].sum()

result = conditional_y_given_x(joint, 0)
print(result)
print(result.sum())   # 1.0

