    return lam / (lam - t)

lam = 2.0
h = 1e-5
derivative_at_0 = (mgf(h, lam) - mgf(-h, lam)) / (2 * h)
print(round(derivative_at_0, 4))

def mgf(t, lam):
    return lam / (lam - t)

lam = 2.0
wrong_variance = mgf(1, lam) - mgf(0, lam) ** 2
